export type Lang = 'en' | 'fr';
const LANG_KEY = 'scoutbox-agent-lang';
let current: Lang = (() => { try { return (localStorage.getItem(LANG_KEY) as Lang) === 'fr' ? 'fr' : 'en'; } catch { return 'en'; } })();
export function getLang(): Lang { return current; }
export function setLang(l: Lang) {
  current = l;
  try { localStorage.setItem(LANG_KEY, l); } catch { /* private mode */ }
  window.dispatchEvent(new Event('sb-lang'));
}
export function t(key: keyof typeof en | (string & {}), fallback?: string): string {
  const dict = current === 'fr' ? fr : en;
  return (dict as Record<string, string>)[key] ?? fallback ?? key;
}
export const fmtDate = (ts: number | string) => new Date(ts).toLocaleDateString(current === 'fr' ? 'fr-FR' : 'en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
export const fmtStamp = (ts: number | string) => {
  const d = new Date(ts);
  const sameDay = d.toDateString() === new Date().toDateString();
  return sameDay ? d.toLocaleTimeString(current === 'fr' ? 'fr-FR' : 'en-GB', { hour: '2-digit', minute: '2-digit' }) : fmtDate(ts);
};
